# Least-squares loss L(w, b) = sum of (w*x + b - y)^2 over three points
data = [(0, 1), (1, 3), (2, 4)]

def loss(w, b):
    return sum((w * x + b - y) ** 2 for x, y in data)

# Grid search: w from 0 to 3 and b from 0 to 2, in steps of 0.1
best = None
for i in range(31):
    for j in range(21):
        w, b = i / 10, j / 10
        L = loss(w, b)
        if best is None or L < best[0]:
            best = (L, w, b)

print("grid minimum:", round(best[0], 4), "at w =", best[1], "b =", round(best[2], 1))
print("exact minimum:", round(loss(1.5, 7 / 6), 4), "at w = 1.5, b = 7/6")

