exercises.solution:
def best_grid_point(data, ws, bs):
    best_loss = None
    best = None
    for w in ws:
        for b in bs:
            loss = sum((w * x + b - y) ** 2 for x, y in data)
            if best_loss is None or loss < best_loss:
                best_loss = loss
                best = [w, b]
    return best
